const MARKER = '    },\n  },\n\n  // -- FAQ --';

const themes = {
  'numbers': `    },\n    'second-grade': {\n      intro: 'Second grade is a transformative year for number sense, the year when children move from thinking about numbers as individual quantities to understanding them as part of a powerful, interconnected system built on place value. Seven- and eight-year-olds are expected to add and subtract fluently within one hundred, understand three-digit numbers as combinations of hundreds, tens, and ones, skip count by fives, tens, and hundreds, and begin exploring the conceptual foundations of multiplication through equal groups and arrays. Number worksheets at this level meet these ambitious expectations with rigorous, varied practice that builds both procedural fluency and deep conceptual understanding. Math worksheets present addition and subtraction problems that require regrouping across tens and hundreds, a challenging cognitive task that demands genuine comprehension of place value rather than rote application of an algorithm. Code-addition challenges incorporate two-digit and three-digit numbers, layering logical sequencing on top of more complex arithmetic. Pattern worksheets reveal the multiplicative structure hidden within our number system, as skip counting by twos, threes, fives, and tens exposes the repeating cycles that form the basis of multiplication tables. Sudoku puzzles at the full nine-by-nine level demand sustained logical reasoning, attention to multiple constraints simultaneously, and the ability to self-correct when a strategy fails, all executive function skills that second graders are actively developing. Chart-count-color activities evolve into data interpretation tasks where children read bar graphs and pictographs to answer comparison questions, building the analytical skills that standardized assessments increasingly test. Math puzzles requiring children to find missing numbers in equations, complete number pyramids, or solve simple two-step word problems build the algebraic reasoning and problem-solving stamina that distinguish competent mathematicians from mere calculators. Second graders are also developing the metacognitive skill of explaining their thinking in writing, and worksheets that ask students to show their work or describe their strategy in words deepen understanding while building mathematical communication skills.',
      objectives: [\n        { skill: 'Add and subtract fluently within 100 using strategies based on place value', area: 'math' },\n        { skill: 'Read and interpret data from bar graphs and pictographs', area: 'cognitive' },\n        { skill: 'Identify and extend skip-counting patterns as a foundation for multiplication', area: 'math' },\n      ],\n      developmentalNotes: 'Seven- and eight-year-olds are developing the ability to hold multiple pieces of information in working memory while performing operations, which is essential for regrouping in addition and subtraction. Their growing capacity for abstract thinking allows them to understand that the digit 4 in 435 represents four hundred, not simply four. Worksheets that require children to decompose numbers, compare multi-digit quantities, and explain their reasoning in writing support this cognitive leap from concrete counting to abstract numerical understanding.',\n      teachingTips: [\n        'Challenge students to solve the same addition or subtraction problem using two different strategies, such as breaking apart by place value and using a number line, then compare the methods to determine which is more efficient for that particular problem.',\n        'Use pattern worksheets as an introduction to multiplication by asking students to notice that skip counting by threes produces the sequence three, six, nine, twelve, then connect this to the idea of three groups of one, three groups of two, and so on.',\n      ],\n      faq: [\n        { question: 'How do number worksheets support the transition from addition to multiplication in second grade?', answer: 'Pattern and skip-counting worksheets reveal the multiplicative structure of numbers by showing that adding equal groups repeatedly produces predictable sequences. When a child skip counts by fives and notices the pattern five, ten, fifteen, twenty, they are building the conceptual foundation for understanding that four groups of five equals twenty, which is the core idea behind multiplication.' },\n        { question: 'What strategies should second graders use for adding and subtracting within 100?', answer: 'Second graders should use multiple strategies flexibly, including breaking numbers apart by place value, using a number line to count on or back, making friendly numbers by rounding and adjusting, and using the relationship between addition and subtraction to check their work. Worksheets that present problems in varied formats encourage this strategic flexibility rather than reliance on a single algorithm.' },\n        { question: 'How can number worksheets help second graders understand three-digit place value?', answer: 'Math worksheets and puzzles that require decomposing numbers into hundreds, tens, and ones, comparing three-digit numbers using inequality symbols, and building numbers from expanded form help children internalize the structure of our base-ten system. When a child repeatedly sees that 347 means three hundreds plus four tens plus seven ones across different worksheet formats, the concept moves from memorized fact to genuine understanding.' },\n      ],\n    },\n  },\n\n  // -- FAQ --`,

  'alphabet': `    },\n    'second-grade': {\n      intro: 'Second grade marks the transition from learning to read to reading to learn, and alphabet-based worksheets at this level shift from letter recognition and basic phonics to the advanced decoding skills, spelling patterns, and vocabulary strategies that fluent reading demands. Seven- and eight-year-olds are expected to read grade-level text with accuracy and fluency, decode words with common prefixes and suffixes, know spelling conventions for long vowel patterns and common irregularities, and use context clues and word structure to determine the meaning of unfamiliar words. Alphabet worksheets at this level support these sophisticated literacy goals through activities that treat letters not as individual units to memorize but as components of a flexible, rule-governed spelling system. Word scramble worksheets present longer, multi-syllable words that challenge students to apply phonics rules and morphological awareness simultaneously, recognizing that un-happy follows a prefix pattern and that jump-ing follows a suffix rule. Image crossword puzzles demand advanced phonemic analysis: students must segment complex words into syllables, identify vowel patterns within each syllable, and select the correct spelling for each sound, a task that integrates phonics, spelling, and vocabulary in a single puzzle. Word searches feature academic vocabulary from science, social studies, and mathematics, building the cross-curricular word knowledge that reading comprehension depends on. Writing worksheets move beyond sentences into organized paragraphs where students apply their spelling knowledge in extended compositions. Word guess activities build inference skills as students use letter patterns, word length, and contextual clues to identify hidden words, mirroring the strategic thinking that skilled readers use when encountering unfamiliar vocabulary in text. Alphabet train activities at this level introduce dictionary and glossary skills, as students practice alphabetical ordering through second and third letters, a practical skill they use daily when looking up words or navigating reference materials.',
      objectives: [\n        { skill: 'Decode words with common prefixes, suffixes, and vowel team patterns', area: 'literacy' },\n        { skill: 'Spell grade-level words correctly using knowledge of spelling conventions and patterns', area: 'literacy' },\n        { skill: 'Use alphabetical order through second and third letters for dictionary and reference skills', area: 'cognitive' },\n      ],\n      developmentalNotes: 'Seven- and eight-year-olds have achieved automatic letter recognition and basic decoding, freeing cognitive resources for higher-level reading processes like fluency, vocabulary acquisition, and comprehension. Their growing morphological awareness, the ability to recognize meaningful word parts like prefixes, suffixes, and root words, accelerates vocabulary growth exponentially. Worksheets that draw attention to these word parts help children see that un-kind and un-fair share a structure, enabling them to decode hundreds of new words by applying a small set of rules.',\n      teachingTips: [\n        'Use word scramble worksheets that focus on word families sharing the same root, prefix, or suffix to help students see spelling as a system of patterns rather than a collection of random letter sequences to memorize.',\n        'Challenge students to complete crossword puzzles without word banks, relying instead on picture clues and their own phonics knowledge to generate spellings independently, building the self-reliance that strong spellers develop.',\n      ],\n      faq: [\n        { question: 'How do alphabet worksheets support second-grade spelling instruction?', answer: 'They provide systematic practice with the spelling patterns second graders study, including long vowel teams, common suffixes like -ed, -ing, and -ly, and high-frequency irregular words. Word scramble, crossword, and word search activities give students multiple exposures to correctly spelled words across different formats, reinforcing the visual memory that accurate spelling requires.' },\n        { question: 'Why is alphabetical order still important in second grade?', answer: 'Second graders use alphabetical order as a practical research tool when navigating dictionaries, glossaries, indexes, and classroom word walls. Alphabet train worksheets that require ordering words by their second or third letter build the precision needed for these real-world reference tasks, making independent learning possible.' },\n        { question: 'How do second-grade word puzzles differ from first-grade ones?', answer: 'Second-grade puzzles feature longer, multi-syllable words with complex spelling patterns, require students to work without word banks more often, and integrate vocabulary from academic content areas like science and social studies. The cognitive demand shifts from simple letter-sound matching to strategic problem-solving using phonics rules, morphological awareness, and contextual reasoning.' },\n      ],\n    },\n  },\n\n  // -- FAQ --`,

  'shapes': `    },\n    'second-grade': {\n      intro: 'Second-grade geometry pushes children beyond naming and describing shapes into genuine spatial reasoning, where they analyze relationships between shapes, partition figures into equal parts to build fraction understanding, and begin developing the measurement concepts that connect geometry to the physical world. Seven- and eight-year-olds are expected to recognize and draw shapes with specified attributes such as a given number of equal sides or a given number of right angles, partition circles and rectangles into two, three, and four equal shares and describe those shares as halves, thirds, and fourths, and understand that equal shares of identical wholes need not have the same shape. Shape worksheets at this level address these rigorous standards through activities that demand analytical thinking rather than simple recognition. Picture-sort worksheets present challenging classification tasks where children must sort shapes by multiple attributes simultaneously, such as identifying all quadrilaterals with at least one pair of parallel sides. Missing-pieces puzzles require children to mentally rotate and flip pieces to determine which one completes a complex design, building the spatial visualization skills that predict STEM achievement. Grid-match activities at this level involve reproducing intricate geometric patterns that include angles, symmetry lines, and proportional relationships, demanding sustained visual attention and precision. Math worksheets integrate geometry with measurement by asking students to calculate the total number of sides across multiple shapes, compare perimeters using informal measurement, and explore the concept of area through counting square units inside rectangular figures. Drawing challenges ask students to partition shapes into equal parts and shade specified fractions, making the connection between geometry and fraction concepts explicit and visual. Pattern worksheets featuring tessellations and symmetrical designs reveal the mathematical beauty hidden in geometric relationships, building aesthetic appreciation alongside analytical skill. Shadow-match and matching activities present three-dimensional shapes and their two-dimensional faces, helping children understand how solid objects relate to flat representations.',
      objectives: [\n        { skill: 'Partition circles and rectangles into halves, thirds, and fourths and describe the equal shares', area: 'math' },\n        { skill: 'Recognize and draw shapes with specific attributes like equal sides and right angles', area: 'math' },\n        { skill: 'Relate two-dimensional faces to three-dimensional solid shapes', area: 'cognitive' },\n      ],\n      developmentalNotes: 'Seven- and eight-year-olds are solidifying their understanding at the van Hiele analysis level, where they can identify and reason about the properties of shapes rather than relying on visual appearance alone. This analytical capacity allows them to understand why a square is a special type of rectangle, why partitioning a circle into three equal parts produces thirds regardless of how the cuts are oriented, and why two different-looking halves of the same rectangle are still equal shares. Worksheets that present these conceptual challenges accelerate the development of formal geometric reasoning.',\n      teachingTips: [\n        'Use partitioning worksheets as a direct bridge to fraction instruction by asking students to shade one-half, one-third, or one-fourth of each shape and then write the fraction notation beside it, connecting visual geometry to symbolic mathematics.',\n        'After completing a grid-match or pattern worksheet, have students identify all lines of symmetry in their completed design, building the habit of looking for mathematical structure within completed work.',\n      ],\n      faq: [\n        { question: 'How do shape worksheets prepare second graders for fraction concepts?', answer: 'Partitioning worksheets ask children to divide circles and rectangles into two, three, and four equal parts, then name each part as a half, third, or fourth. This visual, hands-on experience with equal shares builds the conceptual foundation that fraction arithmetic will later formalize. Children who have repeatedly drawn, shaded, and labeled equal parts of shapes enter fraction instruction with genuine understanding rather than memorized procedures.' },\n        { question: 'What geometry skills should a second grader master by year end?', answer: 'By the end of second grade, children should recognize and draw shapes with specified attributes like five sides or four right angles, partition shapes into equal parts and describe those parts using fraction language, identify faces of three-dimensional shapes as two-dimensional figures, and understand that equal shares of the same shape can look different depending on how the partition is made.' },\n        { question: 'How do grid-match activities build spatial reasoning at the second-grade level?', answer: 'Second-grade grid-match puzzles involve more complex patterns with rotational symmetry, multiple shape types, and proportional relationships. Reproducing these patterns demands mental rotation, careful attention to position and orientation, and the ability to coordinate multiple spatial features simultaneously, all skills that support geometry, engineering, and design thinking.' },\n      ],\n    },\n  },\n\n  // -- FAQ --`,

  'colors': `    },\n    'second-grade': {\n      intro: 'Second graders are ready to explore color as a multidisciplinary concept that connects mathematics, science, and creative expression in sophisticated ways that go well beyond simple naming and sorting. Seven- and eight-year-olds bring fluent color recognition, growing scientific curiosity, and developing analytical skills to color worksheets that challenge them to think quantitatively about color relationships, read and write about color science, and use color vocabulary with precision and nuance. Chart-count-color worksheets at this level involve larger data sets with four or more categories, requiring students to create scaled bar graphs where each square represents two or more items, introducing the concept of scale that connects data representation to multiplication. Addition and subtraction problems use color contexts that involve two-digit numbers: if the art room has forty-five red crayons and twenty-eight blue crayons, how many more red crayons are there, embedding regrouping practice in a familiar visual theme. Pattern worksheets feature complex color sequences including growing patterns where the number of items increases with each repetition, building the multiplicative thinking that second-grade mathematics emphasizes. Picture-sort activities introduce more refined classification criteria, asking students to sort colors along a continuum from warm to cool or arrange tints and shades from lightest to darkest, developing the ordering and comparison skills that support measurement concepts. Find-and-count worksheets present detailed, multi-layered scenes where students must track multiple color categories simultaneously, building the organizational thinking that complex data collection requires. Draw-and-color activities evolve into deliberate design projects where students create artwork following specific color theory constraints, such as using only complementary colors or limiting their palette to three analogous colors. Word searches feature expanded vocabulary including spectrum, pigment, tint, shade, and hue, building the precise scientific language that color discussions require. Writing activities ask students to compose descriptive paragraphs about color observations, connecting visual experience to organized written expression.',
      objectives: [\n        { skill: 'Create and interpret scaled bar graphs using color data with scales of two, five, or ten', area: 'math' },\n        { skill: 'Use precise color vocabulary including tint, shade, warm, cool, and complementary in writing', area: 'literacy' },\n        { skill: 'Apply color theory principles to make deliberate artistic design choices', area: 'creative' },\n      ],\n      developmentalNotes: 'Seven- and eight-year-olds are developing the capacity for systematic observation and recording that scientific inquiry demands. Their ability to organize data into categories, represent it visually, and draw conclusions from the representation is growing rapidly. Color-based data activities provide an ideal context for practicing these skills because the categories are visually obvious, reducing cognitive load so children can focus on the process of data collection and interpretation rather than struggling with the content itself.',\n      teachingTips: [\n        'Connect color chart worksheets to science by having students collect color data from natural objects, such as counting the different colors in a handful of autumn leaves, then represent their findings in a scaled bar graph where each square represents two leaves.',\n        'Use draw-and-color worksheets as a platform for teaching color theory vocabulary by requiring students to label their artwork with terms like warm, cool, complementary, and analogous, building scientific language through creative practice.',\n      ],\n      faq: [\n        { question: 'How do second-grade color worksheets connect to math standards?', answer: 'They address measurement and data standards by requiring students to create and interpret bar graphs with scales greater than one, use addition and subtraction within one hundred to compare color category totals, and identify patterns in color sequences that build multiplicative reasoning. Color provides the accessible content that lets students focus on developing mathematical process skills.' },\n        { question: 'What color science concepts are appropriate for second graders?', answer: 'Second graders can understand primary and secondary color mixing, the difference between tints and shades made by adding white or black, warm and cool color groupings, and the basic idea that light contains a spectrum of colors visible in rainbows. Worksheets that pair these concepts with sorting, labeling, and descriptive writing make abstract science concrete and memorable.' },\n        { question: 'How can color worksheets develop second-grade writing skills?', answer: 'Draw-and-color activities provide vivid visual prompts for descriptive paragraphs where students practice using precise adjectives, organizing sentences into logical order, and supporting opinions with reasons. A student who writes I chose blue and green because they are cool colors that make the ocean scene feel calm is practicing opinion writing, descriptive vocabulary, and color theory simultaneously.' },\n      ],\n    },\n  },\n\n  // -- FAQ --`,

  'school': `    },\n    'second-grade': {\n      intro: 'Second graders have mastered the basics of school life and are ready for worksheets that connect the school environment to increasingly challenging academic content and sophisticated learning-to-learn skills. Seven- and eight-year-olds are expected to work independently for twenty to twenty-five minutes, manage multi-step assignments without constant guidance, collaborate productively with peers on extended projects, take responsibility for organizing their own materials, and reflect on their learning with growing metacognitive awareness. School-themed worksheets at this level reflect these higher expectations while maintaining the familiar, confidence-building context of the classroom environment. Math worksheets present multi-step word problems embedded in school scenarios: if each of the four tables in the classroom has six chairs, how many chairs are there in total, introducing multiplication through school contexts that children experience daily. Subtraction problems involve school supply inventory: the supply closet had seventy-two pencils and the teacher gave out twenty-eight, how many remain, requiring regrouping within the practical context of classroom management. Writing worksheets move beyond sentences into structured paragraphs where students describe their favorite school subject with supporting reasons, explain a classroom procedure step by step, or compose an informational piece about how their school library works. Word searches feature advanced academic vocabulary including curriculum, assignment, encyclopedia, and laboratory, building the sophisticated language that second-grade reading comprehension across subjects demands. Sudoku puzzles at the full nine-cell level develop sustained logical reasoning and the capacity to manage multiple constraints, skills that transfer directly to the increasingly complex academic tasks second graders face. Odd-one-out activities with nuanced distinctions build the analytical precision required for reading comprehension, scientific classification, and mathematical problem-solving. Pattern worksheets featuring school-schedule sequences reinforce the concept that learning follows organized, predictable structures while building algebraic thinking.',
      objectives: [\n        { skill: 'Solve multi-step word problems involving school contexts with addition, subtraction, and early multiplication', area: 'math' },\n        { skill: 'Write organized paragraphs about school topics with a topic sentence and supporting details', area: 'literacy' },\n        { skill: 'Demonstrate independent work habits including self-monitoring and task management over 20-minute sessions', area: 'cognitive' },\n      ],\n      developmentalNotes: 'Seven- and eight-year-olds are developing strong metacognitive skills, the ability to think about their own thinking. They can recognize when they are confused, identify which strategies work best for them, and adjust their approach when something is not working. School-themed worksheets that prompt self-reflection, such as asking students to rate their confidence on each problem or explain which strategy they used, build this metacognitive capacity within the familiar context of classroom learning.',\n      teachingTips: [\n        'Use school-themed multi-step word problems as opportunities to teach problem-solving strategies explicitly, asking students to underline the question, circle the important numbers, and identify the operations needed before solving.',\n        'Assign school-themed writing worksheets as weekly reflection activities where students write about something they learned, a challenge they overcame, or a goal they set, building metacognitive habits within an authentic school context.',\n      ],\n      faq: [\n        { question: 'How do school worksheets support second-grade independence and study skills?', answer: 'Multi-step worksheets that require reading directions carefully, gathering information from multiple sources on the page, performing calculations, and recording answers in an organized format practice the exact task-management sequence that independent academic work demands. Completing these worksheets builds the organizational habits and self-monitoring skills that second graders need across all subjects.' },\n        { question: 'Can school-themed worksheets introduce multiplication concepts?', answer: 'Yes. School scenarios naturally involve equal groups: rows of desks, sets of supplies per student, books on shelves. Word problems like each reading group has four students and there are five groups ask students to find the total, introducing multiplication as repeated addition within a context they understand from daily classroom experience.' },\n        { question: 'How do school vocabulary worksheets prepare second graders for academic reading?', answer: 'Second-grade reading increasingly involves informational texts from science, social studies, and other subjects. Word searches and writing activities featuring academic vocabulary like research, compare, summarize, and organize build familiarity with the cross-curricular language that these texts use, reducing the vocabulary barrier that otherwise slows comprehension of grade-level informational reading.' },\n      ],\n    },\n  },\n\n  // -- FAQ --`,

  'fairy-tales': `    },\n    'second-grade': {\n      intro: 'Second graders bring sophisticated narrative thinking to fairy tale worksheets, ready for activities that move beyond retelling into genuine literary analysis, comparative thinking, and extended creative writing grounded in story structure. Seven- and eight-year-olds can read grade-level fairy tale texts independently, compare characters across different stories, identify the lesson or moral with textual evidence, and write organized paragraphs that express opinions about characters and events. Fairy tale worksheets at this level challenge these growing abilities with multi-step math problems woven into rich narrative contexts: the three brothers divided sixty gold coins equally, but the youngest brother gave ten of his coins to a poor traveler, how many coins does each brother have now, requiring division-as-sharing reasoning followed by subtraction within a compelling story. Reading activities include longer passages that present two versions of the same tale from different cultures, with comprehension questions demanding comparison and inference: how is this version different from the one we read last week, and what does the change tell us about what each culture values. Word searches and word scramble activities feature advanced vocabulary like enchantment, treachery, perseverance, and transformation, building the literary language that enriches both reading comprehension and written expression. Pattern worksheets connect to fairy tale structure by asking children to identify the repeating narrative pattern across multiple stories: character faces a problem, receives magical help, overcomes the challenge, and learns a lesson. Sudoku puzzles with fairy tale character symbols build sustained logical reasoning. Writing workshops use fairy tale prompts that demand organized multi-paragraph responses: retell the story from the villain\\\'s perspective, write an alternate ending that changes the moral, or compare two characters from different tales using evidence from both stories. The combination of beloved literary content with rigorous analytical expectations makes fairy tale worksheets an ideal vehicle for second-grade ELA instruction.',
      objectives: [\n        { skill: 'Compare and contrast characters and themes across multiple fairy tales', area: 'literacy' },\n        { skill: 'Solve multi-step word problems within 100 using fairy tale scenarios', area: 'math' },\n        { skill: 'Write organized opinion paragraphs about characters and morals with supporting evidence', area: 'cognitive' },\n      ],\n      developmentalNotes: 'Seven- and eight-year-olds are developing the ability to hold two perspectives simultaneously, allowing them to compare characters across stories and consider how different versions of the same tale reflect different values. Their growing writing stamina supports multi-paragraph compositions, and their expanding vocabulary allows them to discuss literary concepts like theme, moral, and character motivation with increasing precision and sophistication.',\n      teachingTips: [\n        'Assign comparative worksheets where students analyze two versions of the same fairy tale from different cultures, identifying three similarities and three differences in a structured graphic organizer before writing a comparison paragraph.',\n        'Use fairy tale math word problems that involve multi-step operations as a bridge between arithmetic and algebraic thinking, asking students to identify what information they need and which operations to use before solving.',\n      ],\n      faq: [\n        { question: 'How do fairy tale worksheets develop second-grade critical thinking?', answer: 'They ask students to move beyond retelling into analysis: comparing characters across stories, identifying themes and morals with textual evidence, evaluating character decisions, and considering alternative outcomes. These higher-order thinking tasks align with second-grade reading standards that require students to describe how characters respond to challenges and explain what the story teaches.' },\n        { question: 'Can fairy tale worksheets support second-grade opinion writing?', answer: 'Yes. Prompts like which character was the bravest and why, do you agree with the hero\\\'s decision, and which version of the story teaches a better lesson require students to state an opinion, provide supporting reasons from the text, and organize their ideas into a coherent paragraph, directly addressing second-grade writing standards for opinion pieces.' },\n        { question: 'How do fairy tale math problems differ at the second-grade level?', answer: 'Second-grade fairy tale math involves larger numbers up to one hundred, multi-step problems requiring two or more operations, and early division concepts through treasure-sharing scenarios. Problems demand that students identify relevant information within a story context and select appropriate operations, building the problem-solving skills that distinguish mathematical thinking from simple calculation.' },\n      ],\n    },\n  },\n\n  // -- FAQ --`,

  'pirates': `    },\n    'second-grade': {\n      intro: 'Second graders are ready for pirate worksheets that transform the high-seas adventure into rigorous academic challenges involving multi-step problem solving, map coordinate systems, extended reading comprehension, and structured creative writing. Seven- and eight-year-olds bring fluent addition and subtraction within one hundred, independent reading skills, and developing critical thinking abilities to pirate-themed activities that push every one of these skills forward. Math worksheets present multi-step treasure problems: the pirate crew found eighty-five gold coins on one island and sixty-three on another, but their ship can only carry one hundred coins, how many must they leave behind, requiring addition, comparison, and subtraction across a sequence of operations embedded in an adventure narrative. Grid-coordinate activities become genuine map-reading exercises where students plot locations using letter-number pairs like B4 or D7, building the coordinate system understanding that supports later graphing and geography skills. Reading comprehension worksheets feature longer passages about navigation techniques, famous explorers, and ocean science, with questions that require inference, main idea identification, and connecting information across paragraphs. Word searches and cryptogram puzzles feature advanced vocabulary like navigation, expedition, coordinates, and cartography, building the academic language that second-grade informational reading demands. Treasure hunt worksheets evolve into complex multi-clue investigations where each solved problem reveals a piece of the final answer, requiring students to maintain focus and organization across an extended task. Writing activities move into structured paragraphs: write step-by-step directions for navigating from the ship to the buried treasure, describe the most important qualities a ship captain needs and explain why, or compose a journal entry from a day at sea. The adventure narrative continues to drive engagement while the academic demands fully meet second-grade standards for mathematical reasoning, reading comprehension, and written expression.',
      objectives: [\n        { skill: 'Solve multi-step word problems within 100 using pirate adventure scenarios', area: 'math' },\n        { skill: 'Read and interpret grid coordinates using letter-number pairs for map navigation', area: 'cognitive' },\n        { skill: 'Write organized paragraphs including step-by-step directions and descriptive journal entries', area: 'literacy' },\n      ],\n      developmentalNotes: 'Seven- and eight-year-olds are developing the organizational thinking needed to manage multi-step problems independently, planning their approach before diving in and monitoring their progress as they work. Pirate adventure problems that require sequencing multiple operations provide authentic practice for this executive function development. Their expanding capacity for sustained reading allows them to engage with longer passages about exploration and navigation.',\n      teachingTips: [\n        'Use pirate grid-coordinate worksheets as a direct bridge to math graphing skills by having students plot treasure locations on a coordinate grid and then connect them to discover a hidden shape, making the abstract concept of ordered pairs concrete and exciting.',\n        'Assign pirate journal writing where students compose a day-at-sea entry describing what they saw, what problems they solved, and what they plan to do next, building narrative writing skills within the adventure framework.',\n      ],\n      faq: [\n        { question: 'How do pirate worksheets develop second-grade map and coordinate skills?', answer: 'Grid-coordinate treasure maps require students to use letter-number pairs to identify specific locations, plot routes between multiple points, and describe positions using precise directional language. These skills directly transfer to reading real maps, interpreting data displays, and the coordinate graphing they will encounter in later math courses.' },\n        { question: 'What reading skills do second-grade pirate worksheets develop?', answer: 'They include longer passages about navigation, exploration, and ocean science that require identifying the main idea, making inferences, sequencing events, and connecting information across paragraphs. Cryptogram decoding reinforces letter-pattern recognition and logical deduction. These comprehension skills align with second-grade standards for reading informational and literary text.' },\n        { question: 'How can pirate worksheets help second graders with multi-step problem solving?', answer: 'Treasure adventure problems embed multiple operations within a single narrative scenario, requiring students to identify relevant information, determine the correct sequence of operations, and carry results from one step to the next. This mirrors the multi-step problem-solving process that second-grade math standards emphasize and that real-world quantitative reasoning demands.' },\n      ],\n    },\n  },\n\n  // -- FAQ --`,

  'superheroes': `    },\n    'second-grade': {\n      intro: 'Second graders bring genuine passion and growing analytical skills to superhero worksheets, ready for activities that combine heroic narratives with rigorous academic challenges in mathematics, reading comprehension, and structured writing. Seven- and eight-year-olds can add and subtract fluently within one hundred, read and comprehend grade-level text independently, write organized paragraphs with topic sentences and supporting details, and analyze character traits with increasing depth and nuance. Superhero worksheets at this level present multi-step mission problems: the hero needs to rescue thirty-seven people from one building and forty-eight from another, but her jet can carry only twenty people at a time, how many trips does she need, requiring addition, comparison, and early division reasoning within a narrative that makes every calculation feel consequential. Reading activities include longer hero profiles and mission reports with comprehension questions that demand inference, main idea identification, and distinguishing between fact and opinion: is the narrator describing what happened or giving their opinion about the hero. Word searches and word guess puzzles feature advanced character vocabulary like determination, perseverance, integrity, and sacrifice, building the abstract trait language that second-grade character education and writing standards emphasize. Odd-one-out worksheets present increasingly subtle differences that require careful systematic comparison rather than a quick glance. Drawing activities evolve into design challenges where students create hero profiles with detailed descriptions, power ratings using number scales, and origin stories written as organized paragraphs. Pattern recognition worksheets feature multi-attribute sequences with hero symbols that require identifying and extending rules across two or more changing variables. Sudoku puzzles at the full nine-symbol level build the sustained logical reasoning and self-correction skills that second graders need for increasingly complex academic tasks. The aspirational power of the superhero theme continues to drive extraordinary engagement while the academic demands fully match second-grade rigor.',
      objectives: [\n        { skill: 'Solve multi-step word problems within 100 involving addition, subtraction, and early division', area: 'math' },\n        { skill: 'Analyze character traits and motivations using evidence from text and illustrations', area: 'literacy' },\n        { skill: 'Write organized hero profiles and opinion paragraphs with topic sentences and supporting reasons', area: 'cognitive' },\n      ],\n      developmentalNotes: 'Seven- and eight-year-olds are developing a strong sense of personal identity and values, making superhero identity activities particularly powerful at this age. Their ability to analyze character motivations and articulate why a hero made a specific choice reflects growing perspective-taking and abstract reasoning capacities. Their writing stamina supports multi-paragraph compositions where they can develop ideas with detail and organization.',\n      teachingTips: [\n        'Use superhero mission problems to teach explicit problem-solving strategies: have students draw a diagram of the scenario, identify the question being asked, determine which operations are needed, and solve step by step before checking their answer against the story context.',\n        'Assign comparative character analysis writing where students choose two heroes and write an organized paragraph explaining which one demonstrates a specific trait more effectively, using evidence from worksheets and discussions to support their opinion.',\n      ],\n      faq: [\n        { question: 'How do superhero worksheets build second-grade analytical writing?', answer: 'Hero profile and opinion writing prompts require students to state a claim, provide supporting evidence from the text or illustrations, and organize their ideas with a topic sentence and conclusion. These structured writing tasks directly align with second-grade standards for opinion and informative writing while the superhero context provides the motivation that sustains effort through the challenging process of composing organized paragraphs.' },\n        { question: 'Can superhero worksheets support second-grade character education goals?', answer: 'Yes. The vocabulary of heroism, including words like integrity, perseverance, sacrifice, and responsibility, provides a rich framework for discussing abstract character traits that second graders are developmentally ready to explore. Worksheets that ask students to identify these traits in heroes and then connect them to real-life situations build both vocabulary and moral reasoning.' },\n        { question: 'How do multi-step superhero math problems develop second-grade reasoning?', answer: 'They require students to extract relevant information from a narrative, determine the correct sequence of operations, carry results from one step to the next, and evaluate whether their answer makes sense within the story context. This multi-step reasoning process builds the mathematical problem-solving skills that second-grade standards emphasize and that distinguish real understanding from mechanical calculation.' },\n      ],\n    },\n  },\n\n  // -- FAQ --`,

  'robots': `    },\n    'second-grade': {\n      intro: 'Second graders are ready for robot worksheets that introduce genuine computational thinking alongside rigorous grade-level academics, making the connection between the sequential logic they practice on paper and the technology that surrounds them in the real world. Seven- and eight-year-olds bring fluent arithmetic, growing reading independence, and developing logical reasoning to robot-themed activities that challenge them to think like programmers, write like engineers, and solve problems like computer scientists. Code-addition worksheets at this level present multi-step number sequences requiring addition and subtraction within one hundred, formatted as robot programming instructions that must be executed in precise order, building both arithmetic fluency and algorithmic thinking simultaneously. Pattern worksheets introduce complex multi-variable patterns where both the shape and the color of robot components change according to different rules, requiring students to identify and track multiple patterns at once, a skill directly connected to data analysis and algebraic reasoning. Grid-match activities evolve into symmetry and transformation challenges where students must reproduce a robot design that has been rotated or reflected, building the spatial reasoning that STEM careers depend on. Cryptogram worksheets feature longer encoded messages about robot functions and technology concepts, challenging students to apply logical deduction across extended text while building reading comprehension. Word searches feature advanced STEM vocabulary including algorithm, processor, function, debug, and sequence, building the technical language that computing education requires. Writing worksheets ask students to compose step-by-step instruction sets for a robot to complete a specific task, demanding the precise, sequential thinking that real programming requires. Odd-one-out activities with complex robot designs featuring subtle mechanical differences develop the systematic observation skills that engineering and scientific inquiry demand. Sudoku puzzles with robot symbols at the full nine-cell level build sustained logical reasoning and the capacity to self-correct when an approach fails.',
      objectives: [\n        { skill: 'Write precise step-by-step instructions demonstrating sequential and algorithmic thinking', area: 'cognitive' },\n        { skill: 'Identify and extend multi-variable patterns involving two or more changing attributes', area: 'math' },\n        { skill: 'Apply logical deduction to decode messages and solve multi-step robot programming challenges', area: 'cognitive' },\n      ],\n      developmentalNotes: 'Seven- and eight-year-olds are developing the capacity for systematic thinking, the ability to approach a problem methodically rather than through trial and error. This cognitive milestone makes second grade the ideal time to introduce concepts like debugging, where students identify and correct errors in a sequence of instructions, and algorithmic thinking, where they learn that every complex task can be broken into smaller, ordered steps. Robot worksheets provide the perfect context for these skills because the robot metaphor makes abstract thinking concrete and engaging.',\n      teachingTips: [\n        'Use robot instruction-writing worksheets as a pre-coding activity by having students write the steps for a simple task, then test their instructions by having a classmate follow them literally as a robot would, identifying and fixing any unclear or missing steps.',\n        'Connect pattern worksheets to data analysis by asking students to describe the rule governing each pattern in words, then predict what the tenth or twentieth element would be, building the generalization skills that algebraic thinking requires.',\n      ],\n      faq: [\n        { question: 'How do robot worksheets prepare second graders for formal coding instruction?', answer: 'They build the foundational thinking skills that all coding requires: sequential reasoning through instruction-writing, pattern recognition through multi-variable pattern activities, logical deduction through cryptogram decoding, and debugging through error-identification exercises. Students who develop these skills through robot worksheets transition more smoothly to screen-based coding because they already understand the underlying logic.' },\n        { question: 'What makes second-grade robot worksheets more challenging than first-grade ones?', answer: 'They involve multi-step arithmetic sequences, multi-variable patterns where two or more attributes change simultaneously, longer cryptogram messages requiring sustained logical deduction, and instruction-writing tasks demanding precise sequential language. The cognitive demands match second-grade standards while the robot theme maintains the STEM excitement that drives engagement.' },\n        { question: 'Can robot worksheets develop second-grade writing skills?', answer: 'Yes. Writing step-by-step robot instructions demands the same precise, sequential organization that informational and procedural writing standards require. Students must use transition words like first, next, then, and finally, choose specific verbs, and order their sentences logically. This technical writing practice transfers directly to other informational writing tasks across the curriculum.' },\n      ],\n    },\n  },\n\n  // -- FAQ --`,

  'circus': `    },\n    'second-grade': {\n      intro: 'Second graders bring genuine analytical skills and growing academic stamina to circus worksheets, ready for activities that transform the excitement of performance into rigorous mathematical reasoning, extended reading comprehension, and structured creative writing. Seven- and eight-year-olds can add and subtract fluently within one hundred, read grade-level text independently, write organized paragraphs with supporting details, and engage in sustained problem-solving for twenty minutes or more. Circus worksheets at this level present multi-step performance math: if the circus sells forty-five tickets for the afternoon show and sixty-two for the evening show, and each ticket costs three dollars, how many total tickets were sold and which show earned more money, layering addition, comparison, and early multiplication within the thrilling context of running a circus. Measurement activities use circus contexts naturally: how many feet tall is the tightrope, how many yards long is the parade route, how many minutes does each act last, connecting standard measurement units to engaging real-world scenarios that children can visualize. Reading comprehension worksheets feature longer passages about circus history, performer training, and behind-the-scenes logistics, with questions requiring main idea identification, inference, and connecting details across paragraphs. Word searches and word scramble activities feature advanced vocabulary like equilibrium, coordination, choreography, and spectacle, building the sophisticated language that second-grade academic reading demands. Find-and-count activities evolve into data collection tasks where students survey a detailed circus scene, organize their counts into categories, and create bar graphs with scales greater than one. Draw-and-color activities become design projects where students plan a complete circus show, including a schedule of acts with times, a seating chart with sections and ticket prices, and a poster with persuasive language, integrating math, writing, and creative expression in a single culminating project. Odd-one-out worksheets with subtle differences between performer costumes develop the precise observational skills that scientific inquiry and careful reading both require.',
      objectives: [\n        { skill: 'Solve multi-step word problems involving addition, subtraction, and measurement in circus contexts', area: 'math' },\n        { skill: 'Read longer informational passages about circus topics and answer inference-level comprehension questions', area: 'literacy' },\n        { skill: 'Plan and design a circus show integrating math, writing, and creative expression', area: 'creative' },\n      ],\n      developmentalNotes: 'Seven- and eight-year-olds are developing the capacity for project-based thinking, the ability to work toward a larger goal across multiple steps and sessions. Circus show planning activities tap into this developing capacity by asking students to coordinate multiple elements, from scheduling acts to pricing tickets to designing advertisements, giving them authentic practice with the organizational skills that complex academic projects will increasingly demand.',\n      teachingTips: [\n        'Use circus ticket-sales word problems to introduce multiplication concepts by framing repeated addition visually: if five rows of seats each hold eight people, students can draw the array and count the total, building the conceptual foundation for understanding multiplication as equal groups.',\n        'Assign a circus show planning project where students create a schedule, a budget, and a poster over several sessions, integrating math computation, informational writing, and creative design in a sustained project that mirrors real-world event planning.',\n      ],\n      faq: [\n        { question: 'How do circus worksheets introduce measurement concepts in second grade?', answer: 'Circus contexts naturally involve measurement: the height of a tightrope in feet, the length of a parade route in yards, the duration of each act in minutes, and the weight of equipment in pounds. These authentic scenarios make abstract measurement units concrete and meaningful, helping students understand why standard units exist and how to apply them in real situations.' },\n        { question: 'Can circus worksheets support second-grade project-based learning?', answer: 'Yes. A circus show planning project integrates multiple academic skills in an authentic context: students calculate budgets using addition and subtraction, write persuasive poster text and informational program descriptions, create schedules using time concepts, and design visual materials using color and spatial reasoning. This cross-curricular integration reflects how skills combine in real-world tasks.' },\n        { question: 'How do second-grade circus reading passages differ from earlier grades?', answer: 'Second-grade passages are longer, spanning multiple paragraphs, and include informational content about circus history, performer training, and show logistics alongside narrative descriptions. Comprehension questions require inference, main idea identification, and connecting information across paragraphs rather than simple recall, matching the higher reading standards of second grade.' },\n      ],\n    },\n  },\n\n  // -- FAQ --`,
};

let successCount = 0;

for (const [theme, block] of Object.entries(themes)) {
  const filePath = path.join(BASE, theme, 'en.ts');
  let content = fs.readFileSync(filePath, 'utf8');
  const idx = content.indexOf(MARKER);
  if (idx === -1) {
    console.error('Pattern not found in ' + theme);
    process.exit(1);
  }
  content = content.substring(0, idx) + block + content.substring(idx + MARKER.length);
  fs.writeFileSync(filePath, content, 'utf8');
  console.log('Updated ' + theme);
  successCount++;
}

console.log('\nDone! Updated ' + successCount + ' theme files.');
